// ===== 面板开关 =====
function openPanel(){var m=document.querySelector('.sb-mask'),p=document.querySelector('.sb-panel');if(m&&p){m.style.display='block';p.classList.add('active');}}
function closePanel(){var m=document.querySelector('.sb-mask'),p=document.querySelector('.sb-panel');if(p)p.classList.remove('active');setTimeout(function(){if(m)m.style.display='none';},400);}

// ===== 标签点击 =====
function tc(el,tid){
    el.classList.toggle('active');
    var g=el.parentElement,arr=[];
    g.querySelectorAll('.tag.active').forEach(function(s){arr.push(s.innerText);});
    document.getElementById(tid).value=arr.join('、');
}

// ===== 折叠图鉴 =====
function toggleCat(header){
    var arrow=header.querySelector('.arrow');
    var body=header.nextElementSibling;
    if(body.classList.contains('open')){
        body.classList.remove('open');
        arrow.classList.remove('open');
    }else{
        body.classList.add('open');
        arrow.classList.add('open');
    }
}

// ===== 种族选择 =====
var selectedSpecies={name:'',category:'',desc:''};
function selectSpecies(el,cat,name,desc){
    // 取消之前的选中
    document.querySelectorAll('.species-item.selected').forEach(function(s){s.classList.remove('selected');});
    el.classList.add('selected');
    selectedSpecies={name:name,category:cat,desc:desc};
    updateBloodDisplay();
}

// ===== 混血类型切换 =====
function setType(t){
    document.querySelectorAll('.bt-btn').forEach(function(b){b.classList.toggle('active',b.dataset.t===t);});
