    document.getElementById('cfg_half').style.display=(t==='half')?'block':'none';
    document.getElementById('cfg_chimera').style.display=(t==='chimera')?'block':'none';
    window._bloodType=t;
    updateBloodDisplay();
}
window._bloodType='pure';

// ===== 更新血脉显示 =====
function updateBloodDisplay(){
    var catNames={beast:'兽人系',plant:'植物系',aqua:'水栖系',spirit:'精灵/魔法系',undead:'不死系',insect:'虫系',dragon:'龙系',slime:'不定形系'};
