    }else{
        var catN=catNames[selectedSpecies.category]||'未知';
        var catI=catIcons[selectedSpecies.category]||'❓';
        if(window._bloodType==='pure'){
            s='💎 纯血·'+catI+' '+selectedSpecies.name+' ('+catN+')';
            detail='种族特征：'+selectedSpecies.desc;
        }else if(window._bloodType==='half'){
            var subR=document.getElementById('f_sub_race').value.trim()||'未指定';
            var subT=document.getElementById('f_sub_trait').value.trim()||'';
            var allDom=document.getElementById('halfAllDom').checked;
            s='🔀 半混血·主种族 '+catI+selectedSpecies.name+' / 副种族 '+subR;
