function randomAll(){
    // 清空所有标签
    document.querySelectorAll('.tag').forEach(function(x){x.classList.remove('active');});
    document.querySelectorAll('.species-item.selected').forEach(function(x){x.classList.remove('selected');});

    // 随机种族
    var sp=ALL_SPECIES[Math.floor(Math.random()*ALL_SPECIES.length)];
    selectedSpecies={name:sp.name,category:sp.cat,desc:sp.desc};

    // 尝试在图鉴中高亮对应项
    document.querySelectorAll('.species-item').forEach(function(el){
        var nameEl=el.querySelector('.sp-name');
        if(nameEl && nameEl.textContent.indexOf(sp.name)!==-1){
            el.classList.add('selected');
            // 展开对应分类
            var catBody=el.parentElement;
            var catHeader=catBody.previousElementSibling;
            if(catBody && !catBody.classList.contains('open')){
                catBody.classList.add('open');
                if(catHeader){
                    var arrow=catHeader.querySelector('.arrow');
                    if(arrow) arrow.classList.add('open');
                }
            }
        }
    });

    // 随机混血类型
    var types=['pure','pure','pure','half','chimera'];
    var t=types[Math.floor(Math.random()*types.length)];
    setType(t);

    if(t==='half'){
        var subSp=ALL_SPECIES[Math.floor(Math.random()*ALL_SPECIES.length)];
        while(subSp.name===sp.name) subSp=ALL_SPECIES[Math.floor(Math.random()*ALL_SPECIES.length)];
        document.getElementById('f_sub_race').value=subSp.name;
