// ===== 生成档案 =====
function genChar(){
    var bloodSum=window._bloodSum||'未配置';
    var bloodDet=window._bloodDet||'';

    var r='{character}\n';
    r+='╔══════════════════════════════╗\n';
    r+='║   月见镇·魔物娘NPC角色档案   ║\n';
    r+='╚══════════════════════════════╝\n\n';

    // 种族
    r+='═══ 🧬 种族血脉 ═══\n';
    r+='种族构成：'+bloodSum+'\n';
    if(bloodDet){
        r+='详细特征：\n';
        bloodDet.split('\n').forEach(function(line){
            if(line.trim()) r+='  '+line.trim()+'\n';
        });
    }
    r+='\n';

    // 基础
    r+='═══ 📋 基础信息 ═══\n';
    var fields=[
        ['f_name','姓名'],['f_title','称号/别名'],['f_age','外表年龄','岁'],
        ['f_real_age','实际年龄'],['f_body','身高/体型'],['f_identity','职业/身份']
    ];
    fields.forEach(function(f){
        var el=document.getElementById(f[0]);
        var v=el?el.value.trim():'';
        if(f[0]==='f_age'){
            v=el.value;
            if(v==='999') v='不老不死';
            else v=v+'岁';
        }
        if(v&&v!=='岁') r+=f[1]+'：'+v+'\n';
    });
    r+='\n';

    // 外貌
    r+='═══ ✨ 外貌描写 ═══\n';
    var looks=[['f_face','脸型/五官'],['f_style','穿着风格'],['f_mark','种族外貌特征']];
    looks.forEach(function(f){
        var v=document.getElementById(f[0]).value.trim();
        if(v) r+=f[1]+'：'+v+'\n';
    });
    r+='\n';

    // 性格
    r+='═══ 🧠 性格与内在 ═══\n';
    var inner=[['f_personality','性格关键词'],['f_speech','说话风格'],['f_habit','口癖/口头禅']];
    inner.forEach(function(f){
        var v=document.getElementById(f[0]).value.trim();
        if(v) r+=f[1]+'：'+v+'\n';
    });
    r+='\n';

    // 种族能力
    r+='═══ ⚔️ 种族能力 ═══\n';
    var abilFields=[['f_ability','能力标签'],['f_weakness','弱点标签']];
    abilFields.forEach(function(f){
        var v=document.getElementById(f[0]).value.trim();
        if(v) r+=f[1]+'：'+v+'\n';
    });
    var abilDesc=document.getElementById('f_ability_desc').value.trim();
    if(abilDesc) r+='能力详述：'+abilDesc+'\n';
    r+='\n';

    // 背景
    r+='═══ 📜 背景经历 ═══\n';
    var bg=document.getElementById('f_background').value.trim();
    if(bg) r+='生平履历：'+bg+'\n';
    r+='\n';

    // 自定义
    r+='═══ ⚡ 自定义属性 ═══\n';
    var cst=document.getElementById('f_custom').value.trim();
    if(cst) r+='属性标签：'+cst+'\n';
    var cdesc=document.getElementById('f_custom_desc').value.trim();
    if(cdesc) r+='补充描述：'+cdesc+'\n';
    r+='\n';

    // 身体特征
    r+='═══ 💗 身体特征详设 ═══\n';
    var bodyFields=[['f_chest','胸部'],['f_hip','臀部/下半身'],['f_priv','特殊身体部位']];
