        var v=document.getElementById(f[0]).value.trim();
        if(v) r+=f[1]+'：'+v+'\n';
    });
    var bExtra=document.getElementById('f_body_extra').value.trim();
    if(bExtra) r+='其他补充：'+bExtra+'\n';
    r+='\n';

    r+='{/character}';

